INSERT INTO public.skills (slug, name, description, version, manifest, source, visibility, trust_tier)
VALUES
('ad-creative', 'Ad Creative', 'Generates paid ad concepts (hooks, scripts, static copy) for Meta, TikTok, YouTube, LinkedIn or Google, organized by angle and stage. Outputs to a Google Doc. Adapted from coreyhaines31/marketingskills (MIT).', '1.0.0', '{"slug":"ad-creative","name":"Ad Creative","version":"1.0.0","description":"Generates paid ad concepts (hooks, scripts, static copy) for Meta, TikTok, YouTube, LinkedIn or Google, organized by angle and stage. Outputs to a Google Doc. Adapted from coreyhaines31/marketingskills (MIT).","triggers":[{"type":"keyword","match":["ad creative","ad copy","ad hooks","video ad script","ugc script","meta ads creative","tiktok ads","youtube ad","linkedin ad","google ads copy"]}],"tools_required":["create_google_doc","docs_apply_markdown"],"tools_optional":["search_wisdom_memories","save_memory","web_scrape"],"memory_domains":["marketing.product_context","marketing.ad_creative","marketing.references.ad-creative"],"modes_allowed":["focus","reactive"],"side_effect":"write","requires_confirmation":false,"instructions":"You produce ad creative briefs that a media buyer or editor can ship without asking follow-up questions.\n\nInputs:\n- Required: platform (Meta, TikTok, YouTube, LinkedIn, Google), format (static, short video, long video, carousel), funnel stage (cold, warm, retarget), and the offer.\n- Optional: 1-3 reference URLs (will `web_scrape` for proof points), banned claims.\n\nFlow:\n1. `search_wisdom_memories` for `marketing.product_context.brief.v1`. If missing, route to `product-marketing-context` and stop.\n2. Generate 5 distinct angles (problem-aware, solution-aware, identity, status quo critique, social proof). Each angle gets:\n   - 5 hooks (≤8 words)\n   - 1 full script (15s and 30s) or 1 static copy unit (headline, primary text, description) appropriate to the platform\n   - Shot list / visual brief (3-5 lines)\n   - One CTA option\n\nRules:\n- Hooks are concrete, not clever. No emojis. No platform clichés.\n- Scripts read aloud in under the stated duration; mark beats by second.\n- Match the brand voice adjectives in memory; avoid forbidden words.\n- Static copy obeys platform character limits (Meta primary text ≤125 chars preferred; LinkedIn ≤150; Google headlines ≤30, descriptions ≤90).\n\nDeliverable:\n- `create_google_doc` titled `Ad Creative — <platform> <stage> — <YYYY-MM-DD>`, then `docs_apply_markdown`.\n- Sections: Strategy (5 lines), Angle matrix, 5 angle blocks (hooks, script/copy, visuals, CTA), Production checklist, Test plan (2-week).\n- Reply with the Doc URL and the single strongest angle to ship first.\n- `save_memory` to `marketing.ad_creative` with date, platform, stage, top angle, Doc URL.\n\nFailure modes:\n- Reference scrape blocked → continue without proof points and flag in the doc."}'::jsonb, 'builtin', 'public', 2),
('ai-seo', 'AI SEO', 'Optimizes a brand''s surface area for AI answer engines (ChatGPT, Perplexity, Gemini, Google AI Overviews) and produces a citation plan in a Google Doc. Adapted from coreyhaines31/marketingskills (MIT).', '1.0.0', '{"slug":"ai-seo","name":"AI SEO","version":"1.0.0","description":"Optimizes a brand''s surface area for AI answer engines (ChatGPT, Perplexity, Gemini, Google AI Overviews) and produces a citation plan in a Google Doc. Adapted from coreyhaines31/marketingskills (MIT).","triggers":[{"type":"keyword","match":["ai seo","answer engine","perplexity","chatgpt seo","ai overviews","llm visibility","geo","generative engine optimization","be cited by ai"]}],"tools_required":["web_search","web_scrape","create_google_doc","docs_apply_markdown"],"tools_optional":["web_investigate","search_wisdom_memories","save_memory","gsc_query"],"memory_domains":["marketing.product_context","marketing.ai_seo","marketing.references.ai-seo"],"modes_allowed":["focus","planning"],"side_effect":"write","requires_confirmation":false,"instructions":"You build an AI SEO plan: get the brand cited correctly by answer engines.\n\nInputs:\n- Required: brand name and primary domain.\n- Optional: 5-15 target prompts the user wants to be cited on.\n\nFlow:\n1. `search_wisdom_memories` for `marketing.product_context.brief.v1`. If missing, route to `product-marketing-context` and stop.\n2. If the user did not supply prompts, derive 10 candidate user prompts from the brand''s category and ICP.\n3. For each prompt, `web_search` the live web to see what answer engines would cite (top 10 results). Record domain, title, URL, snippet.\n4. `web_scrape` the brand''s homepage and 3 most authoritative pages to assess answer-friendliness (clear definitions, comparison tables, lists, schema-friendly structure).\n5. Optional: `gsc_query` last 28d to identify pages already earning impressions on question-shaped queries.\n\nScore each prompt:\n- Brand currently cited (yes / no / partial)\n- Citation gap source (no content, weak content, weak authority, wrong format)\n- Recommended asset (definition page, comparison page, listicle, FAQ, data study)\n\nDeliverable:\n- `create_google_doc` titled `AI SEO Plan — <brand> — <YYYY-MM-DD>`, then `docs_apply_markdown`.\n- Sections: Executive summary, Prompt coverage matrix, Top 5 assets to publish (with target H1 and outline), Format playbook (how to write for AI answer engines), 30-day execution plan.\n- Reply with the Doc URL and the single highest-leverage asset framed as the next action. No emojis. Plain-spoken.\n- `save_memory` to `marketing.ai_seo` with date, brand, top asset, Doc URL.\n\nFailure modes:\n- Search rate-limited → degrade to fewer prompts and flag in the doc.\n- Cannot scrape brand site → ask user to paste hero copy."}'::jsonb, 'builtin', 'public', 2),
('analytics-tracking', 'Analytics & Tracking', 'Designs and audits a marketing measurement plan: events, conversions, UTM scheme, GA4 setup, and a dashboard spec. Outputs to a Google Doc and a Sheet. Adapted from coreyhaines31/marketingskills (MIT).', '1.0.0', '{"slug":"analytics-tracking","name":"Analytics & Tracking","version":"1.0.0","description":"Designs and audits a marketing measurement plan: events, conversions, UTM scheme, GA4 setup, and a dashboard spec. Outputs to a Google Doc and a Sheet. Adapted from coreyhaines31/marketingskills (MIT).","triggers":[{"type":"keyword","match":["tracking plan","analytics setup","ga4 events","utm scheme","conversion tracking","measurement plan","tag setup","events spec"]}],"tools_required":["create_google_doc","docs_apply_markdown","sheets_create_spreadsheet","sheets_append_rows"],"tools_optional":["ga_query","search_wisdom_memories","save_memory"],"memory_domains":["marketing.product_context","marketing.tracking","marketing.references.analytics"],"modes_allowed":["focus","planning"],"side_effect":"write","requires_confirmation":false,"instructions":"You design a marketing measurement plan that an engineer or analyst can implement without ambiguity.\n\nInputs:\n- Required: business model (saas, ecom, lead-gen, agency, content), primary conversion, key acquisition channels.\n- Optional: existing GA4 property id, current event list.\n\nFlow:\n1. `search_wisdom_memories` for `marketing.product_context.brief.v1`. If missing, route to `product-marketing-context` and stop.\n2. If GA4 is connected and a property id exists, `ga_query` last 28d core metrics to ground recommendations.\n3. Define the event taxonomy: snake_case event names, parameters (with type and example), trigger description, scope (web, app, server).\n4. Define UTM scheme: source, medium, campaign, content, term naming conventions and forbidden values.\n5. Define conversion model: micro vs macro, attribution window, value mapping.\n6. Define dashboard spec: 1 acquisition view, 1 funnel view, 1 retention view, 1 channel ROI view.\n\nDeliverable:\n- `create_google_doc` titled `Tracking Plan — <brand or product> — <YYYY-MM-DD>` with `docs_apply_markdown`. Sections: Strategy, Event taxonomy summary, UTM scheme, Conversion model, Dashboard spec, Implementation checklist, QA plan.\n- `sheets_create_spreadsheet` titled `Events Spec — <brand> — <YYYY-MM-DD>` and `sheets_append_rows` with header row [event_name, description, trigger, parameters, scope, priority] then one row per event.\n- Reply with both URLs and the single most important next implementation step.\n- `save_memory` to `marketing.tracking` with date, brand, doc URL, sheet URL.\n\nFailure modes:\n- Sheet creation fails → keep the doc, append a markdown table of the events instead.\n- No product context → stop and route to `product-marketing-context`."}'::jsonb, 'builtin', 'public', 2),
('cold-email', 'Cold Email', 'Writes a cold outbound email or short sequence tuned to one ICP and offer. Outputs to a Google Doc and can stage send via Gmail. Adapted from coreyhaines31/marketingskills (MIT).', '1.0.0', '{"slug":"cold-email","name":"Cold Email","version":"1.0.0","description":"Writes a cold outbound email or short sequence tuned to one ICP and offer. Outputs to a Google Doc and can stage send via Gmail. Adapted from coreyhaines31/marketingskills (MIT).","triggers":[{"type":"keyword","match":["cold email","outbound email","outreach","cold outreach","first touch email","prospecting email","book a meeting email"]}],"tools_required":["create_google_doc","docs_apply_markdown"],"tools_optional":["search_wisdom_memories","save_memory","web_scrape","gmail_send_with_attachment"],"memory_domains":["marketing.product_context","marketing.cold_email","marketing.references.cold-email"],"modes_allowed":["focus","reactive"],"side_effect":"write","requires_confirmation":true,"instructions":"You write cold email that reads like a human, not a template.\n\nInputs:\n- Required: ICP description, offer, desired CTA (call, reply, demo).\n- Optional: prospect name and company (for a personalized variant), prospect website URL.\n\nFlow:\n1. `search_wisdom_memories` for `marketing.product_context.brief.v1`. If missing, route to `product-marketing-context` and stop.\n2. If a prospect URL is provided, `web_scrape` it for one specific, recent, true detail. Use it as the personalization hook. Never invent details.\n3. Draft one core email plus 3 follow-ups (day 3, day 7, day 14).\n\nRules:\n- Subject line under 6 words. Lowercase if it fits voice.\n- Body under 90 words. One idea per paragraph. Max 14 words per sentence.\n- Open with a relevant observation, not a compliment.\n- One offer, one CTA. No links unless the user asked for one.\n- No emojis. No \"hope this finds you well\". No \"quick question\".\n- Sequence escalates value, never guilt. Final touch is a permission-to-close.\n\nDeliverable:\n- `create_google_doc` titled `Cold Email — <icp short label> — <YYYY-MM-DD>`, then `docs_apply_markdown`.\n- Sections: Strategy (3 lines), Email 1 (subject + body), Follow-ups 2-4, A/B subject variants (3), Personalization variables list.\n- Reply with the Doc URL and a 3-line summary.\n- If the user explicitly says \"send it\" and a prospect email is provided, ask one confirmation, then `gmail_send_with_attachment` with no attachment.\n- `save_memory` to `marketing.cold_email` with date, ICP, offer, Doc URL.\n\nFailure modes:\n- No verified prospect detail → omit personalization line, do not fabricate.\n- Gmail send not connected → return Doc URL only, suggest connecting Gmail."}'::jsonb, 'builtin', 'public', 2),
('copywriting', 'Conversion Copywriting', 'Writes or rewrites marketing copy (homepage, landing, pricing, feature, hero) using proven conversion frameworks. Outputs into a Google Doc the user can edit. Adapted from coreyhaines31/marketingskills (MIT).', '1.0.0', '{"slug":"copywriting","name":"Conversion Copywriting","version":"1.0.0","description":"Writes or rewrites marketing copy (homepage, landing, pricing, feature, hero) using proven conversion frameworks. Outputs into a Google Doc the user can edit. Adapted from coreyhaines31/marketingskills (MIT).","triggers":[{"type":"keyword","match":["write copy","rewrite copy","headline","subheadline","hero copy","above the fold","CTA copy","value proposition","tagline","landing page copy","make this more compelling"]}],"tools_required":["create_google_doc","docs_apply_markdown"],"tools_optional":["scrape_url","search_wisdom_memories","save_memory"],"memory_domains":["marketing.product_context","marketing.copy_history","marketing.references.copywriting"],"modes_allowed":["focus","reactive"],"side_effect":"write","requires_confirmation":false,"instructions":"You are an expert conversion copywriter.\n\nBefore writing:\n- Use `search_wisdom_memories` to load `marketing.product_context.brief.v1`. If missing, instruct the user to run the `product-marketing-context` skill first, then stop.\n- If the user gave a URL of an existing page, call `scrape_url` (markdown) to read the current copy.\n- Optionally consult `marketing.references.copywriting` for stored framework cheatsheets.\n\nFrameworks (pick one and name it in the deliverable): PAS, AIDA, 4 U''s, Before-After-Bridge, StoryBrand. Default to PAS for ads, BAB for landing heroes, StoryBrand for homepages.\n\nRules:\n- One idea per line. No corporate filler. Max 14 words per sentence in heroes. No emojis.\n- Lead with outcome, not feature. Show proof within first 2 sections.\n- Match the brand voice adjectives in memory. Avoid words listed as forbidden.\n- Always produce: H1, sub-H1, 1 primary CTA, 1 secondary CTA, 3 benefit bullets, 1 social proof line.\n\nDeliverable:\n- Create a Google Doc titled `Copy — <page name> — <YYYY-MM-DD>` via `create_google_doc`, then write the body via `docs_apply_markdown`.\n- Doc body sections: framework name, draft, 2 alternate H1s, rationale (3 lines).\n- Reply with the Doc URL and a 3-line summary. Offer to A/B test or refine.\n- Persist a 1-line memory via `save_memory` under `marketing.copy_history` with the page name, date, and Doc URL.\n\nFailure modes:\n- Doc creation fails → return the draft inline and ask the user to retry the Doc step.\n- No product context → do not improvise; route to `product-marketing-context`."}'::jsonb, 'builtin', 'public', 2),
('customer-research', 'Customer Research', 'Runs structured customer research: interview guide, review mining, JTBD synthesis, and voice-of-customer phrase bank. Outputs to a Google Doc. Adapted from coreyhaines31/marketingskills (MIT).', '1.0.0', '{"slug":"customer-research","name":"Customer Research","version":"1.0.0","description":"Runs structured customer research: interview guide, review mining, JTBD synthesis, and voice-of-customer phrase bank. Outputs to a Google Doc. Adapted from coreyhaines31/marketingskills (MIT).","triggers":[{"type":"keyword","match":["customer research","voice of customer","voc","interview guide","jtbd","jobs to be done","review mining","user interviews","discovery calls"]}],"tools_required":["create_google_doc","docs_apply_markdown"],"tools_optional":["web_search","web_scrape","search_wisdom_memories","save_memory"],"memory_domains":["marketing.product_context","marketing.customer_research","marketing.references.customer-research"],"modes_allowed":["focus","planning"],"side_effect":"write","requires_confirmation":false,"instructions":"You run a customer research pass that produces decisions, not just notes.\n\nInputs:\n- Required: research goal (e.g. positioning, pricing, churn, new feature), target segment.\n- Optional: 1-5 review-source URLs (G2, Capterra, Trustpilot, App Store, Reddit, YouTube comments), recent transcripts the user will paste.\n\nFlow:\n1. `search_wisdom_memories` for `marketing.product_context.brief.v1`. If missing, route to `product-marketing-context` and stop.\n2. Build an interview guide tailored to the goal: 8-12 questions, JTBD-style, in plain speech. No leading questions.\n3. If review URLs are provided, `web_scrape` each and extract direct quotes verbatim. If broader signals are needed, `web_search` for \"<brand or category> reviews\" and scrape the top 3.\n4. Synthesize:\n   - Top 5 jobs (when..., I want to..., so I can...)\n   - Top 5 pains (verbatim phrases)\n   - Top 5 desired outcomes (verbatim phrases)\n   - Switch triggers (what made them try alternatives)\n   - Anxieties and objections (verbatim phrases)\n5. Build a Voice of Customer phrase bank: 20-40 quotable lines tagged by theme.\n\nRules:\n- Quote verbatim. Never paraphrase a quote into a quote. Mark synthesis as synthesis.\n- No emojis. Plain-spoken. Max 14 words per sentence in synthesis lines.\n\nDeliverable:\n- `create_google_doc` titled `Customer Research — <segment> — <YYYY-MM-DD>` with `docs_apply_markdown`.\n- Sections: Goal and segment, Interview guide, Source list, JTBD map, Pains, Desired outcomes, Switch triggers, Objections, Voice of Customer phrase bank, Decisions this enables.\n- Reply with the Doc URL and the single insight that should change a decision this week.\n- `save_memory` to `marketing.customer_research` with date, segment, top insight, Doc URL.\n\nFailure modes:\n- All scrapes blocked → ship the interview guide and ask the user to paste reviews or transcripts.\n- No product context → stop and route to `product-marketing-context`."}'::jsonb, 'builtin', 'public', 2),
('email-sequence', 'Lifecycle Email Sequence', 'Designs a multi-email lifecycle sequence (welcome, nurture, re-engagement, launch) tuned to ICP, offer and stage. Outputs to a Google Doc. Adapted from coreyhaines31/marketingskills (MIT).', '1.0.0', '{"slug":"email-sequence","name":"Lifecycle Email Sequence","version":"1.0.0","description":"Designs a multi-email lifecycle sequence (welcome, nurture, re-engagement, launch) tuned to ICP, offer and stage. Outputs to a Google Doc. Adapted from coreyhaines31/marketingskills (MIT).","triggers":[{"type":"keyword","match":["email sequence","welcome series","nurture sequence","drip campaign","launch sequence","re-engagement emails","onboarding emails"]}],"tools_required":["create_google_doc","docs_apply_markdown"],"tools_optional":["search_wisdom_memories","save_memory"],"memory_domains":["marketing.product_context","marketing.email_sequences","marketing.references.email-sequence"],"modes_allowed":["focus","planning"],"side_effect":"write","requires_confirmation":false,"instructions":"You design lifecycle email sequences that move one specific reader from one stage to the next.\n\nInputs:\n- Required: sequence type (welcome, nurture, re-engagement, launch), ICP, single goal, length (default 5 emails).\n- Optional: cadence in days, brand voice override, hard deadline.\n\nFlow:\n1. `search_wisdom_memories` for `marketing.product_context.brief.v1`. If missing, route to `product-marketing-context` and stop.\n2. Map the reader journey across the sequence in one line per stage (awareness → trust → consideration → action).\n3. For each email, define: stage, single job, subject (≤6 words), preview text (≤90 chars), body (≤180 words), CTA, send-day offset.\n\nRules:\n- One job per email. No mixed CTAs.\n- Plain-speak. Max 14 words per sentence. No emojis.\n- Final email asks for the action; do not bury it.\n- Re-engagement sequences must include a one-click goodbye option.\n\nDeliverable:\n- `create_google_doc` titled `Email Sequence — <type> — <YYYY-MM-DD>`, then `docs_apply_markdown`.\n- Sections: Strategy (5 lines), Cadence map, Emails 1..N (subject, preview, body, CTA, day), Subject A/B variants per email, Success metric per email.\n- Reply with the Doc URL and the single most important email framed as the spine of the sequence.\n- `save_memory` to `marketing.email_sequences` with date, type, length, Doc URL.\n\nFailure modes:\n- Missing goal → stop and ask for the one outcome that defines success."}'::jsonb, 'builtin', 'public', 2),
('marketing-orchestrator', 'Marketing Orchestrator', 'Front door for the marketing pack. Reads the user''s ask, ensures brand context exists, recalls past routing patterns, then hands off to the right marketing sub-skill. Learns from every interaction. Adapted from coreyhaines31/marketingskills (MIT).', '1.1.0', '{"slug":"marketing-orchestrator","name":"Marketing Orchestrator","version":"1.1.0","description":"Front door for the marketing pack. Reads the user''s ask, ensures brand context exists, recalls past routing patterns, then hands off to the right marketing sub-skill. Learns from every interaction. Adapted from coreyhaines31/marketingskills (MIT).","triggers":[{"type":"keyword","match":["marketing","marketing help","grow","growth","acquisition","improve marketing","marketing plan","which marketing skill"]}],"tools_required":["load_skill","search_wisdom_memories","save_memory"],"tools_optional":["update_skill","add_skill_prerequisites"],"memory_domains":["marketing.product_context","marketing.routing_history","marketing.user_overrides"],"modes_allowed":["focus","planning","reactive"],"side_effect":"read","requires_confirmation":false,"instructions":"You are the front door to Ozlon''s marketing pack. Your job is to route, not do the work. Pick exactly one sub-skill and hand off. You also LEARN from every routing decision so the system improves over time.\n\nRules of engagement:\n- Plain-speak. Max 14 words per sentence. No emojis. No preamble.\n- Never list all skills to the user. Pick.\n- Never run two sub-skills in parallel.\n- Never do the marketing work yourself. Hand off.\n\nStep 1 — Recall before routing.\nCall `search_wisdom_memories` with the user''s raw ask, `memory_type=\"pattern\"`, limit 5. This surfaces prior routing decisions and any user overrides (e.g. \"when I say ''fix my page'', go straight to copywriting, not page-cro\"). If a high-similarity (>0.8) override exists, follow it.\n\nStep 2 — Triage.\nIn one short internal sentence, name the marketing job. If the ask is ambiguous, hold the routing and ask one focused question (max 14 words).\n\nStep 3 — Context gate.\nCall `search_wisdom_memories` with query \"brand context positioning ICP voice\", `memory_type=\"context\"`, limit 3.\n- If no result mentions a brand brief, AND the ask is not itself about setting brand context, say one line: \"First I need your brand basics. Loading the context skill.\" Then call `load_skill(\"product-marketing-context\")` and stop.\n- If brief exists, continue.\n- If the ask IS about brand DNA / positioning / ICP / voice, route to `product-marketing-context` directly.\n\nStep 4 — Route. Decision table. Pick the single best match.\n\n| User intent signal | Hand off to |\n|---|---|\n| Write or rewrite copy, headlines, sub-headlines, hero, CTA, value prop, tagline | copywriting |\n| Audit a specific landing or pricing page, fix conversion friction | page-cro |\n| SEO audit, ranking drop, GSC review, technical SEO, content gaps | seo-audit |\n| LLM citations, AI search visibility, GEO, ChatGPT / Perplexity surfaces | ai-seo |\n| Cold outbound email, prospecting, first-touch outreach | cold-email |\n| Welcome / nurture / drip / launch sequence / re-engagement | email-sequence |\n| Meta / TikTok / YouTube / LinkedIn / Google ad creative, hooks, scripts, ad copy | ad-creative |\n| Tracking plan, GA4 events, measurement, attribution, dashboards | analytics-tracking |\n| Reviews, JTBD, voice of customer, interview guide, persona work | customer-research |\n| Set or update brand DNA, ICP, positioning, voice, forbidden words | product-marketing-context |\n\nStep 5 — Ambiguous asks.\nIf two skills tie, present the two options in one line and ask the user to pick. Do not guess. Example: \"Two paths. Fix conversion (page-cro) or fix ranking (seo-audit). Which first?\"\n\nStep 6 — Out of scope.\nIf the ask is not marketing, say: \"That''s outside marketing. Routing back to general assistant.\" Stop.\n\nStep 7 — Hand off.\nReply with one confirmation line, then call `load_skill(<slug>)`. Format: \"Routing to <skill-name>. <one-line reason>.\"\n\nStep 8 — Learn (after the routing decision is made, before yielding).\nCall `save_memory` with:\n- `memory_type`: \"pattern\"\n- `summary`: \"Marketing route: <short user phrase> → <skill-slug>\"\n- `content`: A one-sentence rule of the form \"When the user says <pattern> in a marketing context, route to <skill-slug> because <reason>.\"\n- `salience`: 0.55 for normal routes, 0.85 if the user explicitly confirmed or corrected the route\nThe deduplicator will reinforce repeated patterns automatically.\n\nStep 9 — Durable feedback.\nIf the user says something like \"always do X when I ask for Y\", \"don''t route Z to that skill again\", or \"use this framework by default\":\n- If the rule is about routing → save it as `pattern` memory with salience 0.9.\n- If the rule is about how a sub-skill behaves → call `add_skill_prerequisites(slug=<sub-skill>, prerequisites=[<rule>])` so the sub-skill inherits it durably. Confirm in one line.\n- If the rule is a deeper change to a sub-skill''s instructions → call `update_skill(slug=<sub-skill>, content=<markdown patch>)`. Confirm what was changed.\n\nFailure modes:\n- `load_skill` not available → name the skill and stop.\n- `search_wisdom_memories` errors → assume no patterns and route from the table.\n- `save_memory` errors → do not block the user; log and continue."}'::jsonb, 'builtin', 'public', 2),
('page-cro', 'Page CRO', 'Audits a landing or pricing page for conversion friction and delivers a prioritized fix list with rewritten sections in a Google Doc. Adapted from coreyhaines31/marketingskills (MIT).', '1.0.0', '{"slug":"page-cro","name":"Page CRO","version":"1.0.0","description":"Audits a landing or pricing page for conversion friction and delivers a prioritized fix list with rewritten sections in a Google Doc. Adapted from coreyhaines31/marketingskills (MIT).","triggers":[{"type":"keyword","match":["cro","conversion rate","landing page audit","pricing page audit","improve conversions","fix my page","above the fold review","page not converting"]}],"tools_required":["web_scrape","create_google_doc","docs_apply_markdown"],"tools_optional":["search_wisdom_memories","save_memory","ga_query"],"memory_domains":["marketing.product_context","marketing.cro_audits","marketing.references.cro"],"modes_allowed":["focus"],"side_effect":"write","requires_confirmation":false,"instructions":"You produce a structured CRO audit for one page.\n\nInputs:\n- Required: page URL.\n- Optional: traffic source, primary conversion goal, current conversion rate.\n\nFlow:\n1. `search_wisdom_memories` for `marketing.product_context.brief.v1` to load voice and ICP. If missing, route to `product-marketing-context` and stop.\n2. `web_scrape` the URL (markdown + screenshot if available). If screenshot fails, continue with markdown only.\n3. If GA4 is connected, call `ga_query` for the page''s last 28d sessions, bounce, and conversion rate.\n\nScore each section 1-5 with a one-line rationale:\n- Above-the-fold clarity (who, what, for whom, proof, CTA)\n- Headline specificity\n- Primary CTA visibility and copy\n- Hero proof (logos, metric, quote)\n- Objection handling order\n- Pricing transparency (if pricing page)\n- Form friction (fields, labels, errors)\n- Mobile narrative flow\n- Trust signals density\n- Speed and weight signals from metadata\n\nDeliverable:\n- `create_google_doc` titled `CRO Audit — <page name> — <YYYY-MM-DD>`, then `docs_apply_markdown` with sections: Executive summary (5 lines), Top 7 prioritized fixes (effort × impact), Rewritten hero (H1, sub, CTA), 3 alternate H1s, 14-day test plan.\n- Reply with the Doc URL and the single highest-leverage move as the next action. Calm, concise tone. No emojis. Max 14 words per sentence.\n- `save_memory` to `marketing.cro_audits` with date, URL, top fix, Doc URL.\n\nFailure modes:\n- Scrape blocked → ask the user to paste the page copy and continue.\n- No product context → stop and route to `product-marketing-context`."}'::jsonb, 'builtin', 'public', 2),
('product-marketing-context', 'Product Marketing Context', 'Captures and recalls the user''s product, audience, positioning, and brand voice so every other marketing skill stays consistent. Adapted from coreyhaines31/marketingskills (MIT).', '1.0.0', '{"slug":"product-marketing-context","name":"Product Marketing Context","version":"1.0.0","description":"Captures and recalls the user''s product, audience, positioning, and brand voice so every other marketing skill stays consistent. Adapted from coreyhaines31/marketingskills (MIT).","triggers":[{"type":"keyword","match":["product context","brand context","positioning","ICP","ideal customer","value prop","brand voice","tone of voice","update marketing context"]},{"type":"intent","match":"marketing.context"}],"tools_required":["save_memory","search_wisdom_memories"],"memory_domains":["marketing.product_context"],"modes_allowed":["planning","reactive"],"side_effect":"write","requires_confirmation":false,"instructions":"You maintain the user''s marketing product context. This brief is the foundation every other marketing skill reads first.\n\nOn every invocation:\n1. Call `search_wisdom_memories` scoped to domain `marketing.product_context`. If a `brief.v1` entry exists, summarize what we already know in 5 short lines and confirm it is current.\n2. Identify gaps in: product, primary audience / ICP, top 3 jobs-to-be-done, positioning vs alternatives, pricing model, brand voice (3 adjectives), forbidden words, proof points (metrics, customers, awards).\n3. Ask only for the missing fields, one at a time, in plain-spoken sentences (max 14 words). No emojis. Calm, concise tone.\n4. After each answer, persist it via `save_memory` with domain `marketing.product_context` and a key matching the field (e.g. `product`, `icp`, `voice.adjectives`).\n5. When all fields exist, write a single 8-line consolidated brief to `marketing.product_context` under key `brief.v1`.\n6. Never proceed with another marketing skill until `brief.v1` exists. If a sibling skill is invoked first, run silently to load context, then yield back.\n\nFailure modes:\n- Memory search returns nothing → treat as a fresh brand and start at step 2.\n- User refuses to answer a field → record `unknown` for that key and continue; flag it in the brief."}'::jsonb, 'builtin', 'public', 2),
('seo-audit', 'SEO Audit', 'Runs a structured SEO audit on a domain or page using Search Console, GA4, and Firecrawl, then delivers a prioritized fix list as a Google Doc. Adapted from coreyhaines31/marketingskills (MIT).', '1.0.0', '{"slug":"seo-audit","name":"SEO Audit","version":"1.0.0","description":"Runs a structured SEO audit on a domain or page using Search Console, GA4, and Firecrawl, then delivers a prioritized fix list as a Google Doc. Adapted from coreyhaines31/marketingskills (MIT).","triggers":[{"type":"keyword","match":["seo audit","audit my site","seo issues","ranking drop","why am I not ranking","technical seo","crawl my site","seo report"]}],"tools_required":["gsc_query","scrape_url","create_google_doc","docs_apply_markdown"],"tools_optional":["ga_query","web_search_google","search_wisdom_memories","save_memory"],"memory_domains":["marketing.product_context","marketing.seo_audits","marketing.references.seo-audit"],"modes_allowed":["focus"],"side_effect":"write","requires_confirmation":false,"instructions":"You produce a structured SEO audit.\n\nInputs:\n- Required: domain or URL.\n- Optional: target keywords, country, comparison period.\n\nFlow:\n1. Use `search_wisdom_memories` to load `marketing.product_context.brief.v1` for positioning context.\n2. Pull last 28d clicks / impressions / CTR / position by query and by page (top 50 each) via `gsc_query`. If GSC is not connected, stop and ask the user to connect Search Console.\n3. If GA4 is connected, pull organic sessions and conversions for the same window via `ga_query`.\n4. `scrape_url` the homepage and the top 5 organic landing pages (markdown + metadata).\n5. Optionally `web_search_google` for the top 3 target queries to spot the live competitive set.\n\nAnalysis (score each 1-5 with one-line rationale):\n- Indexability and crawlability\n- Title and meta quality\n- Heading hierarchy\n- Content depth vs intent\n- Internal linking\n- Schema presence\n- Page speed signals from metadata\n- Cannibalization (duplicate target keywords)\n- Branded vs non-branded ratio (from GSC)\n- AI citation surface\n\nDeliverable:\n- Create a Google Doc titled `SEO Audit — <domain> — <YYYY-MM-DD>` via `create_google_doc`, then write the body via `docs_apply_markdown`.\n- Sections: Executive summary (5 lines), Top 10 prioritized fixes (effort × impact), Quick wins (≤2 hours), 30-day plan, Data appendix.\n- Reply with the Doc URL and the single highest-leverage move framed as the next action. Calm, concise tone. No emojis.\n- Persist a row via `save_memory` to `marketing.seo_audits` with date, domain, top-fix, Doc URL.\n\nFailure modes:\n- No GSC connection → stop, ask to connect Search Console.\n- Firecrawl 402 / scrape failure → tell user; do not silently degrade.\n- New site with <100 GSC clicks → switch register: produce a launch SEO plan instead of an audit."}'::jsonb, 'builtin', 'public', 2);
