-- Seed the 11 marketing skills (Marketing Pack) into the public skill catalog.
-- Adapted from coreyhaines31/marketingskills (MIT). Idempotent on slug.


-- Idempotency: if a skill with the same slug already exists, refresh manifest + version.
ON CONFLICT (slug) DO UPDATE SET
  name        = EXCLUDED.name,
  description = EXCLUDED.description,
  version     = EXCLUDED.version,
  manifest    = EXCLUDED.manifest,
  source      = EXCLUDED.source,
  visibility  = EXCLUDED.visibility,
  trust_tier  = EXCLUDED.trust_tier;
